import requests

BASE_URL = "https://api.socbench.example"
item_id = "CHEMICAL_ITEM_ID"

# Retrieve hazard information for the chemical.
hazard_response = requests.get(
    f"{BASE_URL}/item-hazard-info/{item_id}",
    timeout=30,
)
hazard_response.raise_for_status()
hazard_info = hazard_response.json()

# Retrieve the chemical's properties from inventory to use as yield-analysis inputs.
inventory_response = requests.get(f"{BASE_URL}/inventory", timeout=30)
inventory_response.raise_for_status()
inventory = inventory_response.json()

chemical = next(
    (item for item in inventory if str(item.get("itemID", item.get("id", ""))) == item_id),
    None,
)
if chemical is None:
    raise ValueError(f"Chemical {item_id!r} was not found in inventory")

# Use available chemical properties as environmental factors for the yield calculation.
environmental_factors = {
    str(key): str(value)
    for key, value in chemical.items()
    if key not in {"itemID", "id", "name", "quantity"}
    and value is not None
}
environmental_factors["hazard_info"] = str(hazard_info)

yield_response = requests.post(
    f"{BASE_URL}/yield-calculation",
    json={
        "location": "SPECIFY_FOREST_LOCATION",
        "tree_type": "SPECIFY_TREE_TYPE",
        "area_size": 1,
        "environmental_factors": environmental_factors,
    },
    timeout=30,
)
yield_response.raise_for_status()
yield_impact = yield_response.json()

# Add the chemical to inventory for further analysis and tracking.
new_chemical = {
    key: value
    for key, value in chemical.items()
    if key not in {"itemID", "id"}
}
add_response = requests.post(
    f"{BASE_URL}/inventory",
    json=new_chemical,
    timeout=30,
)
add_response.raise_for_status()

