import requests

BASE_URL = "https://api.socbench.example"
product = {
    "name": "EcoCare Daily Cleanser",
    "category": "personal care",
    "ingredients": [
        {"name": "Aqua", "percentage": 70},
        {"name": "Glycerin", "percentage": 10},
        {"name": "Coco-Glucoside", "percentage": 8},
        {"name": "Citric Acid", "percentage": 2},
    ],
    "environmental_details": {
        "packaging": "recyclable",
        "manufacturing": "low-impact",
    },
}

session = requests.Session()

created = session.post(f"{BASE_URL}/products", json=product)
created.raise_for_status()
created_data = created.json()
product_id = created_data.get("id")

regulatory_response = session.post(
    f"{BASE_URL}/regulation-check",
    json={"product": product, "product_id": product_id},
)
regulatory_response.raise_for_status()
regulatory_result = regulatory_response.json()

sustainability_response = session.post(
    f"{BASE_URL}/sustainability-assessment",
    json={"product": product, "product_id": product_id},
)
sustainability_response.raise_for_status()
sustainability_result = sustainability_response.json()

report_response = session.get(f"{BASE_URL}/reports/compliance")
report_response.raise_for_status()
compliance_report = report_response.json()

def is_non_compliant(value):
    if isinstance(value, dict):
        for key, item in value.items():
            if key.lower() in {"compliant", "is_compliant", "compliance_status", "status"}:
                if item is False or (
                    isinstance(item, str)
                    and item.lower() in {"non-compliant", "noncompliant", "failed", "fail"}
                ):
                    return True
            if is_non_compliant(item):
                return True
    elif isinstance(value, list):
        return any(is_non_compliant(item) for item in value)
    elif isinstance(value, str):
        return value.lower() in {"non-compliant", "noncompliant"}
    return False

report_non_compliant = False
if isinstance(compliance_report, dict):
    products = compliance_report.get("products", compliance_report.get("results", []))
    if isinstance(products, list):
        for item in products:
            if isinstance(item, dict) and (
                item.get("id") == product_id or item.get("product_id") == product_id
            ):
                report_non_compliant = is_non_compliant(item)
                break

if is_non_compliant(regulatory_result) or report_non_compliant:
    order_id = created_data.get("order_id") or product.get("order_id")
    if order_id:
        cancel_response = session.delete(f"{BASE_URL}/orders/{order_id}")
        cancel_response.raise_for_status()

